class BankTransfers:
    def encrypt(self, a):
        pass

    def decrypt(self, a):
        pass

class ICICI(BankTransfers):
    def encrypt(self, a):
        result = []
        for char in a:
            result.append(chr(ord(char) + 1))
            result.append('1')
        return ''.join(result)

    def decrypt(self, a):
        result = []
        i = 0
        while i < len(a):
            result.append(chr(ord(a[i]) - 1))
            i += 2
        return ''.join(result)

class HDFC(BankTransfers):
    def encrypt(self, a):
        result = []
        for i, char in enumerate(a):
            if char == ' ':
                result.append(' ')
            else:
                if i % 2 == 0:
                    result.append(chr(ord(char) + 1))
                else:
                    result.append(chr(ord(char) - 1))
        return ''.join(result)

    def decrypt(self, a):
        result = []
        for i, char in enumerate(a):
            if char == ' ':
                result.append(' ')
            else:
                if i % 2 == 0:
                    result.append(chr(ord(char) - 1))
                else:
                    result.append(chr(ord(char) + 1))
        return ''.join(result)

